values(4,'writing','Full Mock · Writing Task 1 + Task 2','published','{"version":"oct4-full-mock-writing-334-v1","mock":true,"duration_seconds":3600,"tasks":[{"task_type":"task1","label":"Writing Task 1","recommended_seconds":1200,"min_words":150,"prompt":"The table presents data on marriage trends and the ages at which people got married in Australia between 1960 and 2000.","instructions":["Summarize the information by selecting and reporting the main features, and make comparisons where relevant."],"visual":{"kind":"table","title":"Marriage trends and average ages in Australia, 1960–2000","headers":["Year","Number of religious marriages","Number of civil marriages","Average age of brides (years)","Average age of grooms (years)"],"rows":[["1960","25,000","8,000","21","24"],["1970","28,000","12,000","23","25"],["1980","50,000","16,000","25","27"],["1990","32,000","23,000","27","30"],["2000","34,000","40,000","30","32"]]}},{"task_type":"task2","label":"Writing Task 2","recommended_seconds":2400,"min_words":250,"prompt":"While university students in some countries are responsible for covering their own tuition fees, governments in other nations provide financial support for these costs.\\n\\nDo the benefits of this approach outweigh its potential drawbacks?","instructions":["Give reasons for your answer and include any relevant examples from your own knowledge or experience."]}]}'::jsonb,now(),now())
